window.VZOROVA_ZKOUSKA = {"sada":"cvicna-3","oficialni":false,"otazky":[{"id":"TR-008","n":1,"lo":"FL-1.2.2","k":"K1","k3":true,"vyber":1,"q":"Jaký je vztah mezi testováním a zajištěním kvality (QA)?","m":["Testování je nadřazená disciplína, jejíž součástí je i zajištění kvality","Testování je nápravný přístup zaměřený na produkt, QA je preventivní přístup zaměřený na procesy","QA je nápravný přístup zaměřený na produkt a provádějí ho výhradně testeři","Testování a QA jsou totéž, oba pojmy lze libovolně zaměňovat"],"ok":[1],"vys":{"a":"Není správně. Testování je hlavní formou řízení kvality (QC), není nadřazené zajištění kvality.","b":"Je správně. Testování je nápravný přístup zaměřený na produkt (forma řízení kvality), QA je preventivní přístup orientovaný na procesy.","c":"Není správně. QA je preventivní a zaměřené na procesy a je odpovědností všech osob v projektu.","d":"Není správně. Sylabus výslovně uvádí, že testování a QA nejsou totéž."},"obecne":"Sylabus 1.2.2: Testování je nápravný přístup zaměřený na produkt a je hlavní formou řízení kvality (QC). QA je preventivní přístup orientovaný na procesy, založený na předpokladu, že dodržování správného procesu vede ke správnému produktu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"}},{"id":"UP-4-07","n":2,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"Ve které z následujících situací NEMUSÍ být týmový přístup vhodný?","m":["<p>Projekty mobilních aplikací<\/p>","<p>Projekty vývoje webu<\/p>","<p>Bezpečnostně kritické projekty<\/p>","<p>Agilní projekty<\/p>"],"ok":[2],"vys":{"a":"Není správně. U projektů mobilních aplikací nic nebrání využití týmového přístupu.","b":"Není správně. U projektů vývoje webu nic nebrání využití týmového přístupu.","c":"Je správně. U bezpečnostně kritických systémů je obvykle nutné zachovat vysokou úroveň nezávislosti testování, proto týmový přístup nemusí být vhodný.","d":"Není správně. Týmový přístup vychází z extrémního programování a v agilních projektech se běžně uplatňuje."},"obecne":"Sylabus 1.5.2: Týmový přístup nemusí být v kontextu projektu vždy vhodnou metodikou. Typickým příkladem je testování bezpečnostně kritických systémů, kdy je nutné zachovat vysokou úroveň nezávislosti testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UP-1-02","n":3,"lo":"FL-1.1.2","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností je příkladem ladění?","m":["Tester znovu otestuje opravu od vývojáře a najde regresi","Tester najde defekt a nahlásí ho","Vývojář provádí testování komponent","Vývojář najde příčinu selhání a opraví defekt"],"ok":[3],"vys":{"a":"Není správně. Jde o konfirmační, resp. regresní testování, které následuje po ladění.","b":"Není správně. Nalezení a nahlášení defektu je součástí testování, ne ladění.","c":"Není správně. Testování komponent je úroveň testování; ladění následuje až po zjištění selhání.","d":"Je správně. Ladění zahrnuje reprodukování selhání, diagnostiku (nalezení defektu) a jeho opravu."},"obecne":"Sylabus 1.1.2: Testování a ladění jsou samostatné činnosti. Testování vyvolává selhání nebo přímo nachází defekty, ladění hledá příčiny selhání (defekty), analyzuje je a odstraňuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.1.2","nazev":"Testování a ladění","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-dva-testovani-a-ladeni"}},{"id":"TR-006","n":4,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Který princip testování vysvětluje, proč opakované provádění stále stejných testovacích případů postupně ztrácí schopnost odhalovat nové defekty?","m":["Testy se opotřebovávají","Kompletní testování není možné","Testování je závislé na kontextu","Shlukování defektů"],"ok":[0],"vys":{"a":"Je správně. Pokud se stejné testy neustále opakují, stávají se méně účinnými a nové defekty neodhalují.","b":"Není správně. Tento princip říká, že nelze otestovat všechny kombinace vstupů, a proto je třeba testy cílit.","c":"Není správně. Tento princip říká, že neexistuje jediný univerzální přístup k testování.","d":"Není správně. Shlukování defektů popisuje, že většinu defektů obsahuje malé množství komponent."},"obecne":"Sylabus 1.3, princip 5: Testy se opotřebovávají. Pokud se stejné testy opakují neustále dokola, stávají se stále méně účinnými. Je proto nutné měnit stávající testy a testovací data, případně vytvořit testy nové (výjimkou je např. automatizované regresní testování).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-5-04","n":5,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Která z následujících činností je součástí testovací analýzy?","m":["Identifikace potřebné infrastruktury a nástrojů.","Vyhodnocení testovatelnosti testovací báze.","Seskupení testovacích skriptů do sad testů.","Analýza ponaučení (lessons learned) za účelem zlepšení procesu."],"ok":[1],"vys":{"a":"Není správně. Identifikace potřebné infrastruktury a nástrojů je součástí návrhu testů.","b":"Je správně. Při testovací analýze jsou testovací báze a testované objekty hodnoceny za účelem posouzení jejich testovatelnosti a identifikace defektů.","c":"Není správně. Seskupování testovacích případů a skriptů do sad testů je součástí implementace testování.","d":"Není správně. Analýza ponaučení probíhá při dokončení testování."},"obecne":"Sylabus 1.4.1: Testovací analýza zahrnuje analýzu testovací báze za účelem identifikace testovatelných užitných vlastností a definování testovacích podmínek. Testovací báze a testované objekty jsou také hodnoceny za účelem posouzení jejich testovatelnosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-6-05","n":6,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících pracovních produktů NENÍ spojen s návrhem testů?<\/p>","m":["Testovací případy","Požadavky na testovací data","Souhrnný report z testování","Testovací listiny"],"ok":[2],"vys":{"a":"Není správně. (Prioritizované) testovací případy jsou typickým výstupem návrhu testů.","b":"Není správně. Požadavky na testovací data jsou výstupem návrhu testů.","c":"Je správně. Souhrnný report z testování je výstupem dokončení testování, nikoli návrhu testů.","d":"Není správně. Testovací listiny jsou podle sylabu výstupem návrhu testů."},"obecne":"Sylabus 1.4.3: Pracovními produkty z návrhu testů jsou (prioritizované) testovací případy, testovací listiny, položky pokrytí, požadavky na testovací data a požadavky na testovací prostředí. Souhrnný report z testování vzniká při dokončení testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UP-3-06","n":7,"lo":"FL-1.4.5","k":"K2","k3":true,"vyber":1,"q":"<p>Kdo je obvykle zodpovědný za vytvoření a aktualizaci plánu testování pro projekt?<\/p>","m":["Tester","Projektový manažer","Vlastník produktu (product owner)","Manažer testování"],"ok":[3],"vys":{"a":"Není správně. Tester se zaměřuje na testovací analýzu, návrh, implementaci a provedení testů.","b":"Není správně. Projektový manažer odpovídá za projekt jako celek a k plánu testování může přispívat, ale obvykle jej nevytváří.","c":"Není správně. Vlastník produktu odpovídá za produktový backlog a priority, nikoli za plán testování.","d":"Je správně. Plánování testování a vytvoření i aktualizace plánu testování je typickým úkolem manažera testování."},"obecne":"Sylabus 1.4.5: Manažer testování má celkovou odpovědnost za proces testování a zaměřuje se především na plánování testování, monitoring a řízení testování a dokončení testování. Vytvoření a aktualizace plánu testování je proto typicky jeho úkolem.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"}},{"id":"UC-1-05","n":8,"lo":"FL-1.5.1","k":"K2","k3":true,"vyber":1,"q":"Která z následujících dovedností NENÍ v sylabu uvedena mezi obecnými dovednostmi, které jsou pro testery obzvláště důležité?","m":["Řízení vlastního času","Důkladnost a komunikační dovednosti","Znalost domény","Technické znalosti"],"ok":[0],"vys":{"a":"Je správně. Řízení času je obecně užitečné, ale sylabus je mezi dovednostmi testera neuvádí.","b":"Není správně. Důkladnost a komunikační dovednosti sylabus výslovně uvádí.","c":"Není správně. Znalost domény pomáhá porozumět koncovým uživatelům a komunikovat s nimi.","d":"Není správně. Technické znalosti zvyšují efektivitu testování, např. použitím vhodných nástrojů."},"obecne":"Sylabus 1.5.1 uvádí jako obecné dovednosti testera znalost testování, důkladnost a pečlivost, komunikační dovednosti a týmovou spolupráci, analytické a kritické myšlení a kreativitu, technické znalosti a znalost domény. Řízení času mezi nimi není.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"}},{"id":"UP-4-09","n":9,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>V jakém okamžiku vývoje softwaru mohou testovací činnosti NEJDŘÍVE začít?<\/p>","m":["<p>Když je dokončen návrh<\/p>","<p>Když je k dispozici pracovní verze požadavků<\/p>","<p>Když je první modul připraven k testování komponent<\/p>","<p>Když je dokončen kód<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testeři mohou revidovat již požadavky, tedy dříve než je dokončen návrh.","b":"Je správně. Testeři se zapojují do revize pracovních produktů, jakmile jsou k dispozici jejich pracovní verze.","c":"Není správně. Statické testování (revize) může začít dávno před dokončením prvního modulu kódu.","d":"Není správně. Čekat na dokončení kódu je v rozporu s principem včasného testování."},"obecne":"Sylabus 2.1.2: v okamžiku, kdy je k dispozici pracovní verze (draft) libovolného pracovního produktu, jsou do jeho revize zapojeni testeři. To jako forma včasného testování a včasné detekce defektů podporuje princip shift left.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UP-6-10","n":10,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE popisuje cyklus vývoje řízeného testy (TDD)?<\/p>","m":["<p>Refaktorovat, napsat kód, napsat test<\/p>","<p>Napsat test, refaktorovat, napsat kód<\/p>","<p>Napsat test, napsat kód, refaktorovat<\/p>","<p>Napsat kód, napsat test, refaktorovat<\/p>"],"ok":[2],"vys":{"a":"Není správně. Toto pořadí neodpovídá TDD – test se má napsat jako první.","b":"Není správně. Refaktorovat lze až existující kód, tedy po jeho napsání.","c":"Je správně. Nejprve se napíše test, poté kód, který test splní, a následně lze testy i kód refaktorovat.","d":"Není správně. V TDD se test píše před kódem, nikoli po něm."},"obecne":"Sylabus 2.1.3: v TDD se nejprve napíší testy, poté kód tak, aby testům vyhovoval, a následně mohou (ale nemusí) být testy i kód refaktorovány.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UP-2-12","n":11,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího NEJLÉPE vystihuje, jak se retrospektiva využívá jako mechanismus zlepšování procesu v softwarových projektech?<\/p>","m":["<p>Ke zlepšení procesů a lidí dochází, když se každý den identifikují zlepšení produktu<\/p>","<p>Retrospektiva umožňuje členům týmu vyventilovat stížnosti a odejít v dobré náladě<\/p>","<p>Na retrospektivě se revidují všechny testovací případy a aktualizují se pro další iteraci<\/p>","<p>Fakta a metriky z uplynulého období umožňují týmu společně navrhnout zlepšení<\/p>"],"ok":[3],"vys":{"a":"Není správně. Retrospektiva se zaměřuje na proces a spolupráci týmu, ne na každodenní zlepšování produktu.","b":"Není správně. Cílem retrospektivy nejsou stížnosti, ale identifikace konkrétních zlepšení procesu.","c":"Není správně. Revize testovacích případů není účelem retrospektivy, ta hodnotí proces jako celek.","d":"Je správně. Tým na základě objektivních informací rozebírá, co se povedlo a co ne, a navrhuje zlepšení."},"obecne":"Sylabus 2.1.6: na retrospektivě účastníci rozebírají, co bylo úspěšné, co se nepovedlo a jak zlepšení zavést. Retrospektivy jsou kritické pro kontinuální zlepšování procesu a doporučená opatření je třeba sledovat.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"UC-2-17","n":12,"lo":"FL-2.1.4","k":"K2","k3":true,"vyber":1,"q":"<p>Vývojový tým pracuje na nové platformě sociální sítě s průběžnými aktualizacemi funkcí. Kvůli častým nasazením je nepraktické po každé změně manuálně testovat všechny funkcionality. Zajištění pozitivní uživatelské zkušenosti však zůstává zásadní.<\/p><p>Které z následujících tvrzení NEJLÉPE popisuje, jak může přístup DevOps v tomto scénáři podpořit testování?<\/p>","m":["<p>DevOps podporuje automatizované regresní testování, které pomáhá včas odhalit defekty a minimalizovat riziko regrese<\/p>","<p>DevOps klade důraz na podrobné uživatelské scénáře pro každou funkci, čímž snižuje potřebu testování uživatelské zkušenosti<\/p>","<p>DevOps vyžaduje, aby testeři před zahájením jakýchkoli testovacích činností počkali na dokončení funkce<\/p>","<p>DevOps zcela odstraňuje potřebu manuálního testování a spoléhá se výhradně na automatizované testování<\/p>"],"ok":[0],"vys":{"a":"Je správně. DevOps minimalizuje riziko regrese díky rozsáhlým automatizovaným regresním testům a rychlé zpětné vazbě.","b":"Není správně. Podrobné uživatelské scénáře potřebu testování uživatelské zkušenosti nesnižují a nejsou podstatou DevOps.","c":"Není správně. DevOps naopak podporuje shift left a testování průběžně během vývoje.","d":"Není správně. Manuální testování z pohledu koncového uživatele je v DevOps stále potřeba."},"obecne":"Sylabus 2.1.4: z pohledu testování DevOps poskytuje rychlou zpětnou vazbu o kvalitě kódu, díky CI podporuje shift left, usnadňuje vytváření stabilních testovacích prostředí, zvyšuje důraz na nefunkcionální charakteristiky kvality, snižuje potřebu opakovaného manuálního testování a minimalizuje riziko regrese díky automatizovaným regresním testům. Manuální testování, zejména z pohledu koncového uživatele, je však stále potřeba.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"}},{"id":"TR-026","n":13,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"Které z následujících tvrzení NEJLÉPE vystihuje rozdíl mezi testováním černé skříňky a testováním bílé skříňky?","m":["Testování bílé skříňky lze použít pouze pro nefunkcionální charakteristiky systému","Testování černé skříňky vychází ze specifikace, testování bílé skříňky ze struktury","Testování černé skříňky se provádí manuálně, testování bílé skříňky automatizovaně","Testování černé skříňky vyžaduje přístup ke zdrojovému kódu testovaného objektu"],"ok":[1],"vys":{"a":"Není správně. Testování bílé skříňky se používá zejména pro funkcionalitu a strukturu kódu, není omezeno na nefunkcionální charakteristiky.","b":"Je správně. Testování černé skříňky je založeno na specifikaci, testování bílé skříňky na vnitřní struktuře (např. kódu).","c":"Není správně. Oba typy testů lze provádět manuálně i automatizovaně.","d":"Není správně. Testování černé skříňky naopak nevychází z vnitřní struktury, přístup ke kódu nepotřebuje."},"obecne":"Sylabus 2.2.2: testování černé skříňky je založeno na specifikaci a odvozuje testy z dokumentace, která nesouvisí s vnitřní strukturou testovaného objektu. Testování bílé skříňky je založeno na struktuře a odvozuje testy z implementace nebo vnitřní struktury systému (kód, architektura, pracovní toky, datové toky).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"TR-081","n":14,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"Která úroveň testování je NEJVHODNĚJŠÍ pro odhalení defektu v logice uvnitř jedné funkce, která dosud nebyla integrována s ostatními komponentami?","m":["Akceptační testování","Systémové integrační testování","Testování komponent","Integrační testování komponent"],"ok":[2],"vys":{"a":"Není správně. Akceptační testování validuje splnění byznysových potřeb, ne logiku jednotlivé funkce.","b":"Není správně. Systémové integrační testování se zaměřuje na rozhraní mezi systémy a externími službami.","c":"Je správně. Testování komponent se zaměřuje na izolované komponenty, a je proto nejvhodnější pro defekty v logice kódu.","d":"Není správně. Integrační testování komponent se zaměřuje na rozhraní a interakce mezi komponentami; funkce ještě integrována není."},"obecne":"Sylabus 2.2.1: testování komponent se zaměřuje na testování izolovaných komponent. Defekty v logice uvnitř jedné komponenty se proto typicky odhalují právě v této úrovni, ještě před integrací s dalšími komponentami.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"UC-3-10","n":15,"lo":"FL-3.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> přínosem včasné a časté zpětné vazby od zainteresovaných stran?<\/p>","m":["<p>Zabraňuje nedorozuměním při definici požadavků.<\/p>","<p>Zajišťuje, aby změny požadavků byly pochopeny a implementovány dříve.<\/p>","<p>Snižuje pracovní zátěž vývojářů, kteří se mohou věnovat výhradně programování.<\/p>","<p>Všechny výše uvedené možnosti jsou přínosy zpětné vazby.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Prevence nedorozumění při definici požadavků je přínosem zpětné vazby.","b":"Není správně. Včasné pochopení a implementace změn požadavků je přínosem zpětné vazby.","c":"Je správně. Snížení pracovní zátěže vývojářů není přínosem zpětné vazby uvedeným v sylabu.","d":"Není správně. Možnost c) přínosem není, takže ne všechny uvedené možnosti jsou přínosy."},"obecne":"Sylabus 3.2.1: častá zpětná vazba od zainteresovaných stran může zabránit nedorozuměním při definici požadavků a zajistit, aby změny požadavků byly správně a včas pochopeny a implementovány. Snížení pracovní zátěže vývojářů mezi přínosy nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"}},{"id":"UC-3-23","n":16,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Kdo při formální revizi odpovídá za identifikaci anomálií (potenciálních defektů) v revidovaném pracovním produktu?<\/p>","m":["<p>Revidující<\/p>","<p>Moderátor<\/p>","<p>Manažer<\/p>","<p>Autor<\/p>"],"ok":[0],"vys":{"a":"Je správně. Revidující provádí revizi a zaznamenává zjištěné anomálie, doporučení a otázky.","b":"Není správně. Moderátor zajišťuje efektivní průběh revizních schůzek.","c":"Není správně. Manažer rozhoduje, co se bude revidovat, a přiděluje zdroje.","d":"Není správně. Autor vytváří a opravuje revidovaný pracovní produkt."},"obecne":"Sylabus 3.2.3 a 3.2.2: revidující provádí revizi – individuálně posuzuje kvalitu pracovního produktu a identifikuje a zaznamenává anomálie. Revidujícím může být člen projektu, odborník na danou problematiku nebo jiná zainteresovaná strana.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"UP-4-15","n":17,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NESOUVISÍ se statickým testováním?<\/p>","m":["<p>Včasné odhalení defektů<\/p>","<p>Příprava testovacích dat<\/p>","<p>Role zapisovatele<\/p>","<p>Kontrola kódu kompilátorem<\/p>"],"ok":[1],"vys":{"a":"Není správně. Statické testování umožňuje odhalit defekty v nejranějších fázích SDLC.","b":"Je správně. Testovací data se připravují pro provádění testů, tedy pro dynamické testování.","c":"Není správně. Zapisovatel je role při revizích, které jsou statickým testováním.","d":"Není správně. Kompilátor kontroluje kód bez jeho spuštění, jde tedy o formu statické analýzy."},"obecne":"Sylabus 3.1: statické testování nevyžaduje spuštění softwaru ani tvorbu testovacích případů. Příprava testovacích dat slouží dynamickému testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"TR-031","n":18,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá nejformálnější typ revize, který se řídí kompletním obecným procesem revize?","m":["Předvedení (walkthrough)","Technická revize","Inspekce","Neformální revize"],"ok":[2],"vys":{"a":"Není správně. Předvedení vede autor a nemusí se řídit kompletním procesem.","b":"Není správně. Technická revize je formální, ale nejformálnějším typem je inspekce.","c":"Je správně. Inspekce je nejformálnějším typem revize a řídí se kompletním obecným procesem.","d":"Není správně. Neformální revize se neřídí definovaným procesem."},"obecne":"Sylabus 3.2.4: inspekce jsou nejformálnějším typem revize, řídí se kompletním obecným procesem (viz 3.2.2) a jejich hlavním cílem je nalézt maximální počet anomálií.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UC-4-63","n":19,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností uvádí VŠECHNY položky, které lze použít k hodnocení pokrytí dosaženého technikami testování černé skříňky?<\/p><ol type=\"A\"><li>Pokryté podmíněné větve<\/li><li>Pokryté třídy ekvivalence<\/li><li>Pokryté hraniční hodnoty<\/li><li>Pokryté platné přechody (pokrytí 0-switch)<\/li><li>Provedené příkazy<\/li><\/ol>","m":["<p>B a C<\/p>","<p>B, C a D<\/p>","<p>A, C a E<\/p>","<p>B, C, D a E<\/p>"],"ok":[1],"vys":{"a":"Není správně. Chybí D – pokrytí platných přechodů je měřítkem pokrytí testování přechodů stavů, tedy techniky černé skříňky.","b":"Je správně. Třídy ekvivalence, hraniční hodnoty i platné přechody jsou položky pokrytí technik černé skříňky.","c":"Není správně. Větve (A) a příkazy (E) jsou položky pokrytí technik bílé skříňky.","d":"Není správně. Příkazy (E) jsou položkou pokrytí testování bílé skříňky."},"obecne":"Sylabus 4.2: položkami pokrytí technik černé skříňky jsou třídy ekvivalence (4.2.1), hraniční hodnoty (4.2.2), sloupce rozhodovací tabulky (4.2.3) a stavy či přechody (4.2.4; pokrytí platných přechodů se nazývá také 0-switch). Větve a příkazy jsou položky pokrytí technik bílé skříňky (4.3).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UP-5-20","n":20,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Počítá se prémie zaměstnance. Délka zaměstnání nemůže být záporná, ale může být nulová. Výše prémie se odvíjí od délky zaměstnání v těchto kategoriích:<\/p><ul><li>2 roky nebo méně,<\/li><li>více než 2 roky, ale méně než 5 let,<\/li><li>5 až 10 let včetně,<\/li><li>více než 10 let.<\/li><\/ul><p>Jaký je minimální počet testovacích případů potřebný k pokrytí všech PLATNÝCH tříd ekvivalence?<\/p>","m":["<p>2<\/p>","<p>3<\/p>","<p>4<\/p>","<p>5<\/p>"],"ok":[2],"vys":{"a":"Není správně. Platné třídy jsou čtyři, dva testy nepokryjí všechny.","b":"Není správně. O jednu méně, než je platných tříd.","c":"Je správně. Každá ze čtyř platných tříd potřebuje alespoň jeden testovací případ.","d":"Není správně. Pátá třída (záporná délka) je neplatná a otázka se ptá jen na platné třídy."},"obecne":"<p>Sylabus 4.2.1: Platné třídy jsou 0 ≤ délka ≤ 2, 2 < délka < 5, 5 ≤ délka ≤ 10 a délka > 10. Pro pokrytí každé z nich je potřeba alespoň jeden testovací případ, tedy 4.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-32","n":21,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete systém vah, který určuje sazby za přepravu pro regionálního internetového distributora autodílů. Kvůli předpisům byl systém upraven tak, aby zásilky nemohly přesáhnout 100 kg. Hmotnost se vybírá z rozbalovacího seznamu s celými hodnotami od 0 do 100 kg; zásilku s hmotností 0 kg systém odmítne. Sazby jsou určeny takto:<\/p><table><tr><th>Hmotnost zásilky<\/th><th>Sazba za přepravu<\/th><\/tr><tr><td>1 až 10 kg<\/td><td>sazba 1<\/td><\/tr><tr><td>11 až 25 kg<\/td><td>sazba 2<\/td><\/tr><tr><td>26 až 50 kg<\/td><td>sazba 3<\/td><\/tr><tr><td>51 až 100 kg<\/td><td>sazba 4<\/td><\/tr><\/table><p>Jako součást návrhu testů černé skříňky chcete použít tříhodnotovou analýzu hraničních hodnot. Kolik různých hodnot musíte otestovat, abyste dosáhli 100% pokrytí?<\/p>","m":["<p>16<\/p>","<p>17<\/p>","<p>18<\/p>","<p>20<\/p>"],"ok":[1],"vys":{"a":"Není správně. 16 hodnot vynechává jednu z položek pokrytí, např. souseda 2 nebo 52.","b":"Je správně. Hraniční hodnoty jsou 0, 1, 10, 11, 25, 26, 50, 51 a 100; jejich sjednocení se zadatelnými sousedy dává 17 různých hodnot.","c":"Není správně. 18 hodnot by vyšlo, kdyby šlo zadat i hodnotu −1 nebo 101; rozbalovací seznam to neumožňuje.","d":"Není správně. 20 hodnot by vyšlo při počítání duplicitních hodnot nebo nezadatelných hodnot mimo rozsah."},"obecne":"Sylabus 4.2.2: při tříhodnotové BVA jsou položkami pokrytí hraniční hodnoty a jejich sousedé. Hraniční hodnoty: 0 (neplatná třída), 1, 10, 11, 25, 26, 50, 51, 100. Sjednocení: 0, 1, 2, 9, 10, 11, 12, 24, 25, 26, 27, 49, 50, 51, 52, 99, 100 = 17 hodnot (−1 a 101 nelze vybrat).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UP-4-22","n":22,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Dálkový vlak má zvláštní pravidla pro jízdenky, která popisuje následující rozhodovací tabulka:<\/p><table><thead><tr><th><\/th><th>P1<\/th><th>P2<\/th><th>P3<\/th><th>P4<\/th><th>P5<\/th><th>P6<\/th><th>P7<\/th><\/tr><\/thead><tbody><tr><th colspan=\"8\">Podmínky<\/th><\/tr><tr><td>Jízdenka 1. třídy<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><\/tr><tr><td>Flexibilní jízdenka 2. třídy<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><\/tr><tr><td>Jednodenní zpáteční jízdenka 2. třídy<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><\/tr><tr><td>Zvýhodněná jízdenka 2. třídy (Super Saver)<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>A<\/td><\/tr><tr><td>Držitel slevové železniční karty<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>A<\/td><td>A<\/td><\/tr><tr><th colspan=\"8\">Akce<\/th><\/tr><tr><td>Smí cestovat<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><\/tr><tr><td>Nárok na přestup do vyšší třídy<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><\/tr><tr><td>Zlevněné jízdné<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>A<\/td><td>N<\/td><\/tr><\/tbody><\/table><p>A = ano, N = ne; P1–P7 = pravidla.<\/p><p>TC 1: Karolína má studentskou slevovou železniční kartu a cestuje s flexibilní jízdenkou 2. třídy.<\/p><p>TC 2: Jakub má seniorskou slevovou železniční kartu a cestuje se zvýhodněnou jízdenkou 2. třídy (Super Saver).<\/p><p>Která možnost uvádí správné akce pro tyto dva testovací případy?<\/p>","m":["<p>Karolína: cestovat NE, přestup ANO, zlevněné jízdné ANO; Jakub: cestovat NE, přestup NE, zlevněné jízdné NE<\/p>","<p>Karolína: cestovat ANO, přestup NE, zlevněné jízdné ANO; Jakub: cestovat NE, přestup ANO, zlevněné jízdné NE<\/p>","<p>Karolína: cestovat ANO, přestup ANO, zlevněné jízdné NE; Jakub: cestovat ANO, přestup ANO, zlevněné jízdné NE<\/p>","<p>Karolína: cestovat ANO, přestup NE, zlevněné jízdné NE; Jakub: cestovat NE, přestup NE, zlevněné jízdné NE<\/p>"],"ok":[0],"vys":{"a":"Je správně. TC 1 odpovídá pravidlu P6 (smí cestovat N, přestup A, zlevněné jízdné A), TC 2 pravidlu P7 (všechny akce N).","b":"Není správně. Podle P6 Karolína cestovat nesmí, ale má nárok na přestup; Jakub podle P7 nárok na přestup nemá.","c":"Není správně. Podle P6 Karolína cestovat nesmí a má nárok na zlevněné jízdné; Jakub podle P7 nesmí cestovat ani přestoupit.","d":"Není správně. Akce pro Jakuba odpovídají P7, ale Karolína podle P6 cestovat nesmí a má nárok na přestup i zlevněné jízdné."},"obecne":"<p>Sylabus 4.2.3: Pro každý testovací případ se najde pravidlo, jehož podmínky odpovídají vstupům, a očekávaný výsledek se odvodí z akcí tohoto pravidla. Karolína (flexibilní jízdenka 2. třídy + slevová karta) spadá do P6, Jakub (Super Saver + slevová karta) do P7.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UC-4-60","n":23,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový model bankomatu obsahuje právě tyto platné přechody:<\/p><table><tr><th>Ze stavu<\/th><th>Událost<\/th><th>Do stavu<\/th><\/tr><tr><td>Start<\/td><td>vložení karty<\/td><td>Čekání na PIN<\/td><\/tr><tr><td>Čekání na PIN<\/td><td>zadání PIN<\/td><td>1. pokus<\/td><\/tr><tr><td>1. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>1. pokus<\/td><td>PIN chybný<\/td><td>2. pokus<\/td><\/tr><tr><td>2. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>2. pokus<\/td><td>PIN chybný<\/td><td>3. pokus<\/td><\/tr><tr><td>3. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>3. pokus<\/td><td>PIN chybný<\/td><td>Zadržení karty<\/td><\/tr><\/table><p>Stavy „Přístup k účtu“ a „Zadržení karty“ jsou koncové. Každý testovací případ začíná ve stavu „Start“ a končí v koncovém stavu.<\/p><p>Jaký MINIMÁLNÍ počet testovacích případů je potřebný k dosažení 100% pokrytí platných přechodů (pokrytí 0-switch)?<\/p>","m":["<p>3<\/p>","<p>4<\/p>","<p>5<\/p>","<p>6<\/p>"],"ok":[1],"vys":{"a":"Není správně. Do koncových stavů vedou 4 různé přechody a každý testovací případ může provést jen jeden z nich; 3 testy nestačí.","b":"Je správně. Každý ze 4 přechodů do koncového stavu vyžaduje vlastní testovací případ a 4 případy zároveň pokryjí všech 8 platných přechodů.","c":"Není správně. 5 testovacích případů není minimum; stačí 4.","d":"Není správně. 6 testovacích případů není minimum; stačí 4."},"obecne":"Sylabus 4.2.4: při pokrytí platných přechodů (0-switch) musí testy provést každý platný přechod. Protože testovací případ končí v koncovém stavu, může provést jen jeden ze 4 přechodů vedoucích do koncových stavů. Stačí 4 případy: Start → Čekání na PIN → 1. pokus → Přístup k účtu; …→ 1. pokus → 2. pokus → Přístup k účtu; …→ 2. pokus → 3. pokus → Přístup k účtu; …→ 3. pokus → Zadržení karty.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UP-2-24","n":24,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Část kódu operačního systému má 1 200 řádků. Obsahuje jediný příkaz IF bez větve ELSE, jehož tělo obsahuje pouze zobrazení chybového hlášení. Kód neobsahuje žádné další rozhodnutí ani cykly. Kolik testovacích případů je MINIMÁLNĚ potřeba k dosažení 100% pokrytí příkazů a kolik k dosažení 100% pokrytí větví?<\/p>","m":["1 pro pokrytí příkazů a 2 pro pokrytí větví","2 pro pokrytí příkazů a 2 pro pokrytí větví","1 200 pro pokrytí příkazů a 2 pro pokrytí větví","1 pro pokrytí příkazů a 1 pro pokrytí větví"],"ok":[0],"vys":{"a":"Je správně. Jeden test s podmínkou splněnou provede všechny příkazy; pro pokrytí větví je třeba ještě test s podmínkou nesplněnou.","b":"Není správně. Pro pokrytí příkazů stačí jediný test, který vstoupí do těla IF.","c":"Není správně. Jeden test provede všechny příkazy, počet řádků kódu nerozhoduje.","d":"Není správně. Test, který zobrazí chybové hlášení, nepokryje větev, kdy podmínka IF není splněna."},"obecne":"<p>Sylabus 4.3.1 a 4.3.2: Test, ve kterém je podmínka IF splněna, provede všechny spustitelné příkazy (100% pokrytí příkazů). Podmíněná větev „nesplněno“ však zůstane nepokryta, proto 100% pokrytí větví vyžaduje dva testy. Pokrytí větví zaručuje pokrytí příkazů, ale ne naopak.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UC-4-77","n":25,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jak se určuje pokrytí příkazů?<\/p>","m":["<p>Počet pokrytých výsledků rozhodnutí vydělený celkovým počtem výsledků rozhodnutí, v procentech<\/p>","<p>Počet pokrytých spustitelných příkazů vydělený celkovým počtem spustitelných příkazů, v procentech<\/p>","<p>Počet provedených příkazů vydělený celkovým počtem řádků kódu včetně komentářů, v procentech<\/p>","<p>Počet provedených testovacích případů vydělený počtem navržených testovacích případů, v procentech<\/p>"],"ok":[1],"vys":{"a":"Není správně. Výsledky rozhodnutí se týkají pokrytí větví, nikoli příkazů.","b":"Je správně. Pokrytí příkazů je podíl spustitelných příkazů pokrytých testy ze všech spustitelných příkazů, obvykle v procentech.","c":"Není správně. Jmenovatelem jsou spustitelné příkazy, nikoli všechny řádky kódu včetně komentářů.","d":"Není správně. Podíl provedených testů je metrika postupu testování, nikoli pokrytí příkazů."},"obecne":"<p><strong>Podle sylabu (kap. 4.3.1):<\/strong> Při testování příkazů jsou položkami pokrytí spustitelné příkazy. Cílem je navrhovat takové testovací případy, které pokryjí příkazy v určité části kódu při definované akceptovatelné úrovni pokrytí. <strong>Pokrytí se měří jako počet spustitelných příkazů pokrytých testy k celkovému počtu spustitelných příkazů v kódu (obvykle vyjádřeno v procentech).<\/strong><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"UP-1-27","n":26,"lo":"FL-4.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE popisuje průzkumné testování?<\/p>","m":["<p>Testování založené na zkušenostech, znalostech a intuici testera.<\/p>","<p>Praxe testování, při které se k identifikaci potenciálních slabin, jež jsou následně prověřovány testovacími případy, používá hloubkové zkoumání pozadí testovaného objektu.<\/p>","<p>Přístup k testování, při kterém testeři dynamicky navrhují a provádějí testy na základě svých znalostí, průzkumu testované položky a výsledků předchozích testů.<\/p>","<p>Přístup k návrhu testů, při kterém jsou testovací činnosti plánovány jako nepřerušované relace testovací analýzy a návrhu testů, často ve spojení s kontrolními seznamy.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Jde o definici testování založeného na zkušenostech obecně, ne konkrétně průzkumného testování.","b":"Není správně. Průzkumné testování se často provádí při nedostatku času, takže hloubkové zkoumání pozadí testovaného objektu je nepravděpodobné.","c":"Je správně. Testy se při průzkumném testování souběžně navrhují, provádějí a vyhodnocují, zatímco tester získává znalosti o testovaném objektu.","d":"Není správně. Popis vychází z definice testování v relacích, ale provádění testů je v něm nahrazeno testovací analýzou."},"obecne":"<p>Sylabus 4.4.2: Při průzkumném testování jsou testy současně navrhovány, prováděny a vyhodnocovány, zatímco testeři získávají znalosti o testovaném objektu.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"}},{"id":"UP-2-26","n":27,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":2,"q":"<p>Která DVĚ z následujících tvrzení vysvětlují, proč je odhadování chyb užitečnou technikou testování?<\/p>","m":["<p>Může pomoci odvodit testovací případy na základě analýzy specifikačních dokumentů.<\/p>","<p>Může identifikovat testy, které formální techniky snadno nezachytí.<\/p>","<p>Umí dobře využít zkušenosti testera a dostupná data o defektech.<\/p>","<p>Nachází více defektů než formálnější techniky návrhu testů<\/p>"],"ok":[1,2],"vys":{"a":"Není správně. Odhadování chyb nevychází z analýzy specifikace, ale ze znalostí a zkušeností testera.","b":"Je správně. Techniky založené na zkušenostech mohou odhalit defekty, které techniky černé a bílé skříňky neodhalí.","c":"Je správně. Odhadování chyb využívá znalosti testera o tom, jak aplikace fungovala dříve, o typických chybách vývojářů a o selháních v podobných aplikacích.","d":"Není správně. Není zaručeno, že najde více defektů; techniky založené na zkušenostech jsou doplňkem formálních technik."},"obecne":"<p>Sylabus 4.4 a 4.4.1: Odhadování chyb předvídá výskyt chyb, defektů a selhání na základě znalostí a zkušeností testera (včetně údajů o defektech). Techniky založené na zkušenostech mohou odhalit defekty, které jiné techniky přehlédnou, a jsou jejich doplňkem.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UP-5-28","n":28,"lo":"FL-4.5.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jakou roli hraje konverzace při společném psaní uživatelských scénářů?<\/p>","m":["<p>Pomáhá týmu pochopit, jak bude software používán, a vyjasnit požadavky.<\/p>","<p>Určuje prioritu uživatelských scénářů na základě jejich obchodní hodnoty.<\/p>","<p>Slouží zainteresovaným stranám jako prostředek k vyjednávání změn uživatelských scénářů.<\/p>","<p>Zajišťuje, že uživatelské scénáře jsou napsány ve formátu, který je malý, nezávislý a testovatelný.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Konverzace vysvětluje, jak bude software používán, a pomáhá vyjasnit požadavky a nejednoznačnosti.","b":"Není správně. Prioritu určuje typicky vlastník produktu, např. při plánování iterace, ne konverzace.","c":"Není správně. Hlavním účelem konverzace není vyjednávání změn, ale společné porozumění tomu, jak bude software používán.","d":"Není správně. Vlastnosti INVEST jsou kritéria kvality scénáře; konverzace je jedna ze tří částí 3C, ne nástroj formátování."},"obecne":"<p>Sylabus 4.5.1: Uživatelský scénář má tři části (3C): karta, konverzace a potvrzení. Konverzace vysvětluje, jak bude software používán (může být dokumentovaná nebo jen verbální), a spolupráce umožňuje týmu získat společnou vizi toho, co má být dodáno.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.1","nazev":"Společné psaní uživatelských scénářů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-jedna-spolecne-psani-uzivatelskych-scenaru"}},{"id":"UP-6-29","n":29,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující uživatelský scénář:<\/p><p><em>Jako online nakupující<\/em><\/p><p><em>chci přidávat položky do svého nákupního košíku,<\/em><\/p><p><em>abych je mohl později zakoupit.<\/em><\/p><p><br><\/p><p>Akceptační kritéria:<\/p><ul><li><p>Uživatel se může přihlásit na nákupní platformu.<\/p><\/li><li><p>Uživatel může vyhledávat položky.<\/p><\/li><li><p>Uživatel může přidávat položky do nákupního košíku.<\/p><\/li><li><p>Uživatel může zobrazit nákupní košík.<\/p><\/li><li><p>Uživatel může odebírat položky z nákupního košíku.<\/p><\/li><li><p>Uživatel může s položkami v košíku přejít k pokladně.<\/p><\/li><\/ul><p>Která z následujících možností je NEJLEPŠÍM příkladem testu ATDD pro tento uživatelský scénář?<\/p>","m":["<p>Otestovat, zda uživatel může zobrazit historii svých dřívějších objednávek<\/p>","<p>Otestovat, zda uživatel může přidat položku do košíku a poté košík zobrazit<\/p>","<p>Otestovat, zda uživatel může uložit platební kartu pro budoucí nákupy<\/p>","<p>Otestovat, zda uživatel může přesunout položku z košíku do seznamu přání<\/p>"],"ok":[1],"vys":{"a":"Není správně. Historie objednávek není předmětem tohoto uživatelského scénáře ani jeho akceptačních kritérií.","b":"Je správně. Test přímo ověřuje akceptační kritéria „Uživatel může přidávat položky do nákupního košíku“ a „Uživatel může zobrazit nákupní košík“.","c":"Není správně. Ukládání platební karty akceptační kritéria nezmiňují; test by přesahoval rámec uživatelského scénáře.","d":"Není správně. Seznam přání v akceptačních kritériích není; test by přesahoval rámec uživatelského scénáře."},"obecne":"Sylabus 4.5.3: v ATDD se testovací případy odvozují z akceptačních kritérií; musí pokrývat charakteristiky uživatelského scénáře a neměly by přesahovat jeho rámec. Jediný test, který odpovídá akceptačním kritériím, je přidání položky do košíku a jeho zobrazení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UP-2-33","n":30,"lo":"FL-5.1.6","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je klíčovým přínosem konceptu testovací pyramidy?<\/p>","m":["Zajištění stejného počtu testovacích případů na všech úrovních testování","Zvýšení závislosti na manuálním testování na vyšších úrovních","Pomoc při rozvržení úsilí věnovaného automatizaci testů na jednotlivých úrovních","Upřednostnění testů GUI před testy komponent a integračními testy"],"ok":[2],"vys":{"a":"Není správně. Na nižších úrovních má být testů více, na vyšších méně.","b":"Není správně. Zvýšení závislosti na manuálním testování není cílem ani přínosem testovací pyramidy.","c":"Je správně. Testovací pyramida je pomůckou pro určení míry automatizovaných testů a rozložení úsilí mezi vrstvy.","d":"Není správně. Pyramida naopak ukazuje, že testů GUI (E2E) má být méně než testů na nižších úrovních."},"obecne":"Sylabus 5.1.6: Testovací pyramida ukazuje, že testy mohou mít různou granularitu, a pomáhá týmu určit míru automatizace testů rozložením pracnosti mezi jednotlivé vrstvy. Ve spodních vrstvách je mnoho malých, rychlých a izolovaných testů, v horní jen několik E2E testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"}},{"id":"UP-6-30","n":31,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je příkladem dobrého výstupního kritéria systémového testování?<\/p>","m":["<p>Vývojáři musí potvrdit, že je systém hotový.<\/p>","<p>Testování musí trvat nejméně čtyři týdny.<\/p>","<p>Musí být nalezeny všechny defekty v systému.<\/p>","<p>Musí být vyřešeny všechny defekty se závažností 1.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Subjektivní prohlášení vývojářů není měřitelná míra důkladnosti ani binární kritérium splnění testovacích úkolů.","b":"Není správně. Pevně daná minimální délka testování neříká nic o dosažené důkladnosti testování ani o kvalitě systému.","c":"Není správně. Nalezení všech defektů nelze dosáhnout ani ověřit – kompletní testování není možné.","d":"Je správně. Počet nevyřešených defektů (zde kritických) je podle sylabu typickým měřitelným výstupním kritériem."},"obecne":"Sylabus 5.1.3: Typická výstupní kritéria zahrnují míry důkladnosti (např. dosažená úroveň pokrytí, počet nevyřešených defektů, hustota defektů) a binární kritéria ano/ne (např. provedení plánovaných testů). Vyřešení všech defektů nejvyšší závažnosti je měřitelné a splnitelné kritérium; ostatní možnosti měřitelné nebo splnitelné nejsou.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"TR-089","n":32,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"Tým používá tříbodový odhad: nejoptimističtější odhad je 4 člověkohodiny, nejpravděpodobnější odhad 10 člověkohodin a nejpesimističtější odhad 22 člověkohodin. Jaký je výsledný odhad podle vzorce E = (a + 4 × m + b) / 6?","m":["10 člověkohodin","11 člověkohodin","12 člověkohodin","22 člověkohodin"],"ok":[1],"vys":{"a":"Není správně. 10 je pouze nejpravděpodobnější odhad m, nikoli vážený průměr.","b":"Je správně. E = (4 + 4 × 10 + 22) / 6 = 66 / 6 = 11 člověkohodin.","c":"Není správně. 12 je prostý aritmetický průměr (4 + 10 + 22) / 3, nikoli vážený průměr tříbodového odhadu.","d":"Není správně. 22 je nejpesimističtější odhad b."},"obecne":"Sylabus 5.1.4: Výsledný odhad tříbodového odhadu je vážený aritmetický průměr E = (a + 4 × m + b) / 6. Zde (4 + 40 + 22) / 6 = 11 člověkohodin.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-4-32","n":33,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Před vytvořením faktury je nutný účet. Před založením účtu je nutný uživatel účtu (který účet založí). Software se dodává pouze s hlavním uživatelem, který může vytvářet jen jiné typy uživatelů. K otestování struktury softwaru na vysoké úrovni byly napsány tyto testovací případy:<\/p><p>TC1 – Vytvořit fakturu<br>TC2 – Upravit fakturu<br>TC3 – Zpracovat fakturu (odeslat zákazníkovi)<br>TC4 – Smazat fakturu<br>TC5 – Vytvořit účet<br>TC6 – Vytvořit uživatele účtu<br>TC7 – Upravit uživatele účtu<br>TC8 – Smazat uživatele účtu<br>TC9 – Upravit účet<br>TC10 – Smazat účet<\/p><p>Která z následujících testovacích procedur by umožnila provést všechny testy?<\/p>","m":["TC5, TC9, TC1, TC3, TC2, TC4, TC6, TC7, TC8, TC10","TC6, TC7, TC5, TC9, TC1, TC2, TC3, TC4, TC10, TC8","TC5, TC9, TC6, TC7, TC1, TC3, TC2, TC4, TC8, TC10","TC6, TC7, TC1, TC3, TC2, TC4, TC5, TC9, TC10, TC8"],"ok":[1],"vys":{"a":"Není správně. Účet (TC5) se zakládá dříve, než existuje uživatel účtu (TC6).","b":"Je správně. Uživatel účtu → účet → faktura (vytvořit, upravit, zpracovat, smazat) → smazání účtu → smazání uživatele; všechny závislosti jsou splněny.","c":"Není správně. Účet (TC5) se zakládá dříve, než existuje uživatel účtu (TC6).","d":"Není správně. Faktura (TC1) se vytváří dříve, než je založen účet (TC5)."},"obecne":"Sylabus 5.1.5: Při sestavování harmonogramu provádění je nutné respektovat logické závislosti mezi testovacími případy. Hlavní uživatel nejprve vytvoří uživatele účtu (TC6), ten založí účet (TC5), k němuž lze vytvořit fakturu (TC1); mazání probíhá v opačném pořadí (faktura, účet, uživatel). Jediné vyhovující pořadí je d.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-2-34","n":34,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"<p>Který testovací kvadrant bude NEJPRAVDĚPODOBNĚJI obsahovat testy, které ověřují interakce mezi komponentami?<\/p>","m":["<p>Kvadrant Q1<\/p>","<p>Kvadrant Q2<\/p>","<p>Kvadrant Q3<\/p>","<p>Kvadrant Q4<\/p>"],"ok":[0],"vys":{"a":"Je správně. Q1 (zaměřený na technologii a podporu týmu) obsahuje testy komponent a integrační testy komponent, které ověřují interakce mezi komponentami.","b":"Není správně. Q2 obsahuje funkcionální testy, příklady, testy uživatelských scénářů, UX prototypy, testování API a simulace.","c":"Není správně. Q3 obsahuje průzkumné testování, testování použitelnosti a uživatelské akceptační testování.","d":"Není správně. Q4 obsahuje smoke testy a nefunkcionální testy (kromě testů použitelnosti)."},"obecne":"Sylabus 5.1.7: Kvadrant Q1 (zaměřený na technologii a podporu týmu) obsahuje testy komponent a integrační testy komponent. Integrační testy komponent se zaměřují právě na interakce a rozhraní mezi komponentami.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"TR-072","n":35,"lo":"FL-5.2.3","k":"K2","k3":true,"vyber":1,"q":"Analýza produktových rizik určila u platební funkce vysoké riziko (vysoký dopad i vysokou pravděpodobnost). Jak by se to mělo NEJPRAVDĚPODOBNĚJI projevit v testování?","m":["Testování platební funkce se odloží na konec, až bude systém stabilnější","Platební funkce se otestuje stejně důkladně jako ostatní, aby bylo pokrytí rovnoměrné","Platební funkce se otestuje jen průzkumným testováním bez dalších technik","Platební funkce dostane vyšší prioritu a důkladnější testování"],"ok":[3],"vys":{"a":"Není správně. Oblasti s vysokým rizikem se naopak testují dříve, aby se závažné problémy odhalily včas.","b":"Není správně. Testování založené na rizicích rozděluje úsilí podle úrovně rizika; rovnoměrné rozložení vysoké riziko nezohledňuje.","c":"Není správně. Vysoké riziko vyžaduje důkladnější testování, typicky s formálními technikami a vyšším požadovaným pokrytím.","d":"Je správně. Výsledky analýzy rizik určují rozsah, pokrytí a priority testování; vysoké riziko vede k vyšší prioritě a důkladnějšímu testování."},"obecne":"Sylabus 5.2.3: Výsledky analýzy produktových rizik se používají k určení rozsahu testování, technik, požadovaného pokrytí, odhadu pracnosti a priorit testování. Vysoká úroveň rizika vede k důkladnějšímu a dřívějšímu testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.3","nazev":"Analýza produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-tri-analyza-produktovych-rizik"}},{"id":"UC-5-34","n":36,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> součástí obsahu souhrnného reportu z testování?<\/p>","m":["<p>Nová a změněná rizika během testovacího období.<\/p>","<p>Vyhodnocení kvality produktu na základě původního plánu testování.<\/p>","<p>Odchylky od plánu testování.<\/p>","<p>Neošetřená rizika, nevyřešené defekty.<\/p>"],"ok":[0],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.3.2) obsahuje souhrnný report z testování mj. vyhodnocení testování a kvality produktu na základě původního plánu testování, odchylky od plánu testování a neošetřená rizika a nevyřešené defekty. „Nová a změněná rizika během testovacího období“ jsou obsahem <strong>reportu o postupu prací při testování<\/strong>.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"TR-076","n":37,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"Testovací skript odkazoval na starou verzi testovacích dat, což způsobilo falešné selhání testu. Které opatření by tomu NEJLÉPE předešlo?","m":["Po každém selhání testu obnovit testovací data ze zálohy","Verzovat testovací data spolu s odpovídající verzí testovaného objektu","Před každým během testů ručně zkontrolovat obsah testovacích dat","Opakovat test automaticky, pokud první pokus selže"],"ok":[1],"vys":{"a":"Není správně. Obnovení ze zálohy nezaručí, že data odpovídají verzi testovaného objektu.","b":"Je správně. Konfigurační management zajistí jednoznačnou identifikaci verzí a vztahů mezi testovacími daty a testovaným objektem.","c":"Není správně. Ruční kontrola je pracná a náchylná k chybám a neřeší příčinu, kterou je chybějící řízení verzí.","d":"Není správně. Opakování testu se zastaralými daty povede ke stejnému falešnému selhání."},"obecne":"Sylabus 5.4: Konfigurační management zajišťuje, že všechny konfigurační položky (včetně testovacích dat a testovaného objektu) jsou jednoznačně identifikovány a verzovány, jejich vztahy zaznamenány a testware se na ně jednoznačně odkazuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-1-38","n":38,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testovací inženýr testuje videopřehrávač (videorekordér) a zaznamená tento report:<\/p><p>Název: Rychlé převíjení vpřed se zastaví po 2 minutách. Děje se to pokaždé.<br>Očekávaný výsledek: Rychlé převíjení vpřed pokračuje až do konce pásky.<br>Závažnost: Vysoká<br>Priorita: Naléhavá<\/p><p>Kterou důležitou informaci inženýr vynechal?<\/p>","m":["Historii všech změn stavu tohoto reportu","Skutečný výsledek pozorovaný při provedení testu","Identifikaci testovaného objektu (verze softwaru a hardwaru)","Nápady na zlepšení použitého testovacího případu"],"ok":[2],"vys":{"a":"Není správně. U nového reportu historie změn ještě neexistuje; stav a jeho změny obvykle eviduje nástroj pro management defektů.","b":"Není správně. Skutečný výsledek je uveden již v názvu – převíjení se zastaví po 2 minutách.","c":"Je správně. Bez identifikace testovaného objektu a prostředí nelze selhání spolehlivě reprodukovat.","d":"Není správně. Nápady na zlepšení testovacího případu do reportu o defektu nepatří."},"obecne":"Sylabus 5.5: Report o defektu obvykle obsahuje identifikaci testovaného objektu a testovacího prostředí. Bez ní vývojář neví, kterou verzi softwaru a hardwaru má zkoumat.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-2-39","n":39,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících nástrojů je NEJUŽITEČNĚJŠÍ pro reportování metrik testování?<\/p>","m":["<p>Nástroj pro management defektů<\/p>","<p>Nástroj pro statickou analýzu<\/p>","<p>Nástroj pro měření pokrytí<\/p>","<p>Nástroj pro management testování<\/p>"],"ok":[3],"vys":{"a":"Není správně. Nástroj pro management defektů pokrývá jen defekty, ne celkový stav testování.","b":"Není správně. Nástroj pro statickou analýzu hodnotí kód, metriky provádění testů nesleduje.","c":"Není správně. Nástroj pro měření pokrytí měří jen pokrytí kódu, ne celkový postup testování.","d":"Je správně. Nástroj pro management testování spravuje požadavky, testy, výsledky a defekty, a proto umí reportovat souhrnné metriky testování."},"obecne":"Sylabus 6.1: nástroje pro management testování zvyšují efektivitu testování usnadněním správy SDLC, požadavků, testů, defektů a konfigurací. Díky tomu jsou nejužitečnější pro reportování metrik testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UC-6-07","n":40,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností správně uvádí možný přínos automatizace testů?<\/p>","m":["<p>Kratší doba provádění testů<\/p>","<p>Univerzální nástroje, které dokážou otestovat jakýkoli systém<\/p>","<p>Nižší pracnost testování za cenu delší doby provádění testů<\/p>","<p>Méně času pro testery na návrh nových testů<\/p>"],"ok":[0],"vys":{"a":"Je správně. Kratší doba provádění testů umožňuje dřívější odhalení defektů a rychlejší zpětnou vazbu.","b":"Není správně. Nástroje nejsou univerzální; výběr nevhodného nástroje je naopak riziko.","c":"Není správně. Automatizace dobu provádění testů zkracuje, ne prodlužuje.","d":"Není správně. Automatizace testerům naopak uvolní čas na návrh nových, hlubších testů."},"obecne":"Sylabus 6.2 uvádí mezi přínosy automatizace kratší dobu provádění testů, která vede k dřívějšímu odhalení defektů, rychlejší zpětné vazbě a rychlejšímu uvedení na trh, a také více času pro testery na návrh nových testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}}]};
